//! Original source-exact local recovery/isolation fixtures. No model quality claims.
use lightog_core::{common::{canonical_hash as hash,text_sha},knowledge_build,support_selection};
use serde_json::{json,Value};
fn fixture(text:&str,surface:&str)->Value{
 let digest=text_sha(text);let n=text.encode_utf16().count();
 let snapshot=json!({"base_ref":"local_mention_authored","source_epoch":0,"graph_revision":null,"sources":[{"source_ref":"src","source_revision":"v1","original_sha256":digest,"text_sha256":digest,"parser_version":"authored/1"}]});
 let fragment=json!({"id":"ev","origin":"SOURCE_FRAGMENT","source_ref":"src","source_revision":"v1","block_ref":"b","text_sha256":digest,"span":{"start":0,"end":n,"quote":text,"offset_unit":"utf16_code_unit"},"claim_refs":[],"role":"PRIMARY"});
 let es=json!({"contract_version":"lightog-demand/0.1","evidence_set_id":"es","snapshot":snapshot,"fragments":[fragment]});
 let context=json!({"examples":{"es":es},"source_texts":[{"source_ref":"src","source_revision":"v1","text":text,"original_sha256":digest,"parser_version":"authored/1","blocks":[{"block_ref":"b","start":0,"end":n}]}],"authority":{"requests":[],"allowed_snapshots":[snapshot],"claims":[],"receipts":[],"scope_bindings":[],"entities":[],"predicate_refs":[],"user_definitions":[],"groups":[],"entity_links":[]}});
 let prepared=knowledge_build::prepare_extract(&json!({"evidence_set_ref":"es","cq_guidance":"Original authored source","trusted_context":context})).unwrap();
 let raw=json!({"entities":[{"local_id":"bad","surface":surface,"type_label":null,"mention_evidence_id":"ev","mention_occurrence":1},{"local_id":"oak","surface":"Oak","type_label":null,"mention_evidence_id":"ev","mention_occurrence":1}],"candidates":[attribute("bad"),attribute("oak")]});
 json!({"prepared":prepared,"trusted_context":context,"raw":raw,"unit_id":"authored_local","max_candidates":8})
}
fn attribute(subject:&str)->Value{json!({"kind":"ATTRIBUTE","subject_local_id":subject,"predicate":{"label":"role","description":"Original role proposal","evidence_ids":["ev"]},"object":{"entity_local_id":null,"typed_value":{"kind":"STRING","value":"proposed role"}},"direction":"NONE","description":"Original unverified proposal, never semantic certification.","keywords":[],"qualifiers":{"scope":null,"modality":"REPORTED","negated":false,"unit":null,"effective_time":null},"conditions":[],"support_roles":{"assertion":["ev"],"subject_scope":[],"antecedent":[],"condition":[]}})}
fn run(p:&Value)->Value{support_selection::execute("materialize_local_required_occurrence_v1",p).unwrap()}
#[test]fn unique_whitespace_recovery_preserves_original_term_utf16_raw_and_replay(){
 let p=fixture("😀 SOP \t层 handles a step. Oak remains.","SOP层");let original=p.clone();let out=run(&p);assert_eq!(p,original);assert_eq!(out["candidates"].as_array().unwrap().len(),2);
 let row=&out["entity_resolution"][0];assert_eq!(row["entity"]["label"],"SOP \t层");assert_eq!(row["entity"]["mentions"][0]["span"]["start"],3);assert_eq!(row["occurrence_selection"]["model_surface"],"SOP层");assert_eq!(row["occurrence_selection"]["match_mode"],"UNIQUE_WHITESPACE_DIFFERENCE");assert_eq!(out["proposal_contract_version"],support_selection::LOCAL_REQUIRED_OCCURRENCE_VERSION);assert_eq!(out["original_support_selection_raw_sha256"],hash(&p["raw"]));
 for c in out["candidates"].as_array().unwrap(){let r=out["receipts"].as_array().unwrap().iter().find(|r|r["candidate_id"]==c["candidate_id"]).unwrap();support_selection::validate_receipt(c,r,&p["prepared"]).unwrap();assert_eq!(r["semantic_support_certified"],false);}
 let c=&out["candidates"][0];let mut r=out["receipts"][0].clone();r["mention_occurrence_selection"]["selections"][0]["source_surface"]=json!("forged");assert!(support_selection::validate_receipt(c,&r,&p["prepared"]).is_err());
}
#[test]fn ambiguous_whitespace_is_not_resolved_by_ordinal_and_only_dependents_are_isolated(){let p=fixture("SOP 层 one. SOP\n层 two. Oak remains.","SOP层");let out=run(&p);assert_eq!(out["entity_resolution"][0]["error_code"],"ENTITY_SURFACE_WHITESPACE_AMBIGUOUS");assert_eq!(out["entity_resolution"][0]["choices"].as_array().unwrap().len(),2);assert_eq!(out["candidates"].as_array().unwrap().len(),1);assert_eq!(out["quarantined"].as_array().unwrap().len(),1);assert_eq!(out["candidates"][0]["entities"][0]["label"],"Oak");}
#[test]fn no_source_match_punctuation_case_or_parentheses_are_not_fuzzily_repaired(){for (text,surface) in [("Alpha（甲） Oak","Alpha(甲)"),("A-B Oak","AB"),("SOP 层 Oak","sop层"),("Only Oak here.","Absent")]{let out=run(&fixture(text,surface));assert_eq!(out["entity_resolution"][0]["status"],"QUARANTINED");assert_eq!(out["entity_resolution"][0]["choices"],json!([]));assert_eq!(out["candidates"].as_array().unwrap().len(),1);}}
#[test]fn required_missing_float_and_bad_entity_shape_are_local_while_raw_json_duplicates_remain_global(){for mode in 0..3{let mut p=fixture("SOP 层 Oak","SOP层");match mode{0=>{p["raw"]["entities"][0].as_object_mut().unwrap().remove("mention_occurrence");},1=>p["raw"]["entities"][0]["mention_occurrence"]=json!(1.0),_=>p["raw"]["entities"][0]["unexpected"]=json!(true)}let out=run(&p);assert_eq!(out["candidates"].as_array().unwrap().len(),1);assert_eq!(out["entity_resolution"][0]["status"],"QUARANTINED");}
 let mut p=fixture("SOP 层 Oak","SOP层");let raw=serde_json::to_string(&p["raw"]).unwrap().replacen("\"mention_occurrence\":1","\"mention_occurrence\":1.0",1);p["raw"]=json!(raw);assert_eq!(run(&p)["candidates"].as_array().unwrap().len(),1);p["raw"]=json!("{\"entities\":[],\"entities\":[],\"candidates\":[]}");assert!(support_selection::execute("materialize_local_required_occurrence_v1",&p).is_err());
}
#[test]fn registered_subject_unregistered_object_and_bad_registered_object_propagate_only_explicit_dependencies(){let mut p=fixture("SOP 层 Oak","Absent");for object in ["bad","unregistered"]{let mut r=attribute("oak");r["kind"]=json!("RELATION");r["direction"]=json!("DIRECTED");r["object"]=json!({"entity_local_id":object,"typed_value":null});p["raw"]["candidates"].as_array_mut().unwrap().push(r);}let out=run(&p);assert_eq!(out["candidates"].as_array().unwrap().len(),1);assert_eq!(out["quarantined"].as_array().unwrap().len(),3);assert_eq!(out["quarantined"][2]["entity_errors"][0]["error_code"],"ENTITY_REFERENCE_UNKNOWN");assert_eq!(out["symbol_projection"]["missing_key_map"].as_array().unwrap().len(),1);}
#[test]fn host_choice_is_exact_bounded_replayable_and_does_not_rewrite_raw(){let mut p=fixture("SOP 层 one. SOP\t层 two. Oak.","SOP层");let first=run(&p);let choice=&first["entity_resolution"][0]["choices"][1];let original=p["raw"].clone();p["host_resolutions"]=json!([{"registry_index":0,"choice_id":choice["choice_id"]}]);let out=run(&p);assert_eq!(p["raw"],original);assert_eq!(out["candidates"].as_array().unwrap().len(),2);assert_eq!(out["entity_resolution"][0]["entity"]["mentions"][0]["span"]["start"],choice["start"]);let c=&out["candidates"][0];support_selection::validate_receipt(c,&out["receipts"][0],&p["prepared"]).unwrap();p["host_resolutions"][0]["choice_id"]=json!(format!("mention_choice_{}","0".repeat(32)));assert_eq!(support_selection::execute("materialize_local_required_occurrence_v1",&p).unwrap_err().code,"LOCAL_MENTION_HOST_CHOICE_INVALID");}
#[test]fn optional_and_old_strict_ops_do_not_silently_adopt_the_new_resolution_policy(){let p=fixture("SOP 层 Oak","SOP层");assert!(support_selection::execute("materialize_required_occurrence_v1",&p).is_err());let local=run(&p);let c=&local["candidates"][0];let mut r=local["receipts"][0].clone();r["proposal_contract_version"]=json!(support_selection::REQUIRED_OCCURRENCE_VERSION);assert!(support_selection::validate_receipt(c,&r,&p["prepared"]).is_err());}
#[test]fn correction_exclusions_remain_raw_bound_and_are_not_semantic_negative_decisions(){let mut p=fixture("SOP 层 Oak","SOP层");let original=p["raw"].clone();p["host_resolutions"]=json!([]);p["excluded_fact_indices"]=json!([0]);let out=support_selection::execute("materialize_local_correction_v1",&p).unwrap();assert_eq!(p["raw"],original);assert_eq!(out["candidates"].as_array().unwrap().len(),1);assert_eq!(out["quarantined"][0]["error_code"],"HOST_EXCLUDED_CANDIDATE");assert_eq!(out["proposal_contract_profile"]["excluded_fact_indices"],json!([0]));let c=&out["candidates"][0];let r=&out["receipts"][1];support_selection::validate_receipt(c,r,&p["prepared"]).unwrap();assert!(support_selection::execute("materialize_local_required_occurrence_v1",&p).is_err());p["excluded_fact_indices"]=json!([99]);assert!(support_selection::execute("materialize_local_correction_v1",&p).is_err());}
#[test]fn recovery_cannot_search_other_evidence_even_when_target_exists_in_full_source(){let mut p=fixture("Irrelevant heading.\nSOP 层 Oak.","SOP层");let text=p["trusted_context"]["source_texts"][0]["text"].as_str().unwrap().to_owned();let at=text.find('\n').unwrap()+1;let parent=p["trusted_context"]["examples"]["es"]["fragments"][0].clone();let mut first=parent.clone();first["span"]=json!({"start":0,"end":at,"quote":&text[..at],"offset_unit":"utf16_code_unit"});let mut second=parent;second["id"]=json!("other");second["span"]=json!({"start":at,"end":text.encode_utf16().count(),"quote":&text[at..],"offset_unit":"utf16_code_unit"});p["trusted_context"]["examples"]["es"]["fragments"]=json!([first,second]);p["prepared"]=knowledge_build::prepare_extract(&json!({"evidence_set_ref":"es","cq_guidance":"same local direction","trusted_context":p["trusted_context"]})).unwrap();p["raw"]["entities"][1]["mention_evidence_id"]=json!("other");p["raw"]["candidates"][1]["predicate"]["evidence_ids"]=json!(["other"]);p["raw"]["candidates"][1]["support_roles"]["assertion"]=json!(["other"]);let out=run(&p);assert_eq!(out["entity_resolution"][0]["choices"],json!([]));assert_eq!(out["entity_resolution"][0]["status"],"QUARANTINED");assert_eq!(out["candidates"].as_array().unwrap().len(),1);}
#[test]fn exact_repeated_mentions_keep_explicit_position_and_semantics_are_not_rewritten(){let mut p=fixture("😀 SOP 层 first. SOP 层 second. Oak.","SOP 层");p["raw"]["entities"][0]["mention_occurrence"]=json!(2);p["raw"]["candidates"][0]["qualifiers"]["negated"]=json!(true);p["raw"]["candidates"][0]["description"]=json!("An intentionally false unverified statement.");let out=run(&p);assert_eq!(out["entity_resolution"][0]["occurrence_selection"]["match_mode"],"EXACT");assert_eq!(out["entity_resolution"][0]["occurrence_selection"]["ordinal"],2);assert_eq!(out["candidates"][0]["qualifiers"]["negated"],true);assert_eq!(out["candidates"][0]["description"],"An intentionally false unverified statement.");assert_eq!(out["semantic_support_certified"],false);}
